  const item=normalized.items.find(row=>row.key===key);
  need(item,'RESEARCH_OCCURRENCE_NOT_FOUND');
  const occurrenceId='o_'+hash(editionId+'\n'+key);
  const sourceId='s_'+hash(canonicalSource(item,occurrenceId));
