    !/^[\/\\]|^[A-Za-z]:/.test(value) && !/[\\\u0000-\u001f\u007f]/.test(value) &&
    value.split('/').every(part => part && part !== '.' && part !== '..'), 'CROSSREF_DOCUMENT_FILENAME_INVALID');
  return value;
}
